//! The AI info page's settings, from the `[seo.ai_page]` table of
//! `site.toml` (phase GEO, P3).
//!
//! The page tells a reader, human or model, plainly who runs the site,
//! what it covers, how to cite it and how to reach the team. It works
//! with scripts off, because it is plain HTML generated by the site.

use std::collections::BTreeMap;

use serde::Deserialize;

use crate::Locale;

/// The AI info page settings. Every one has a default, so the table may
/// be left out and the page is simply on. `covers` and `cite` are in the
/// main language; a table per other language gives that copy its own:
///
/// ```toml
/// [seo.ai_page]
/// off = true           # switch the page off
/// contact = "team@example.com"   # how to reach the team
///
/// [seo.ai_page.text.de]
/// covers = "Verständliche Anleitungen zu SEO."
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Default, Deserialize)]
#[serde(default, deny_unknown_fields)]
pub struct AiPageSettings {
    /// Switch the page off. `false`, the default, keeps it: a site that
    /// says nothing about itself for models leaves them to guess.
    pub off: bool,
    /// How to reach the team, shown on the page as the contact line. An
    /// address, such as `team@example.com`; the publisher's public
    /// address is used when this is left out.
    pub contact: Option<String>,
    /// What the site covers, in one sentence, when the tagline does not
    /// say it already.
    pub covers: Option<String>,
    /// How the site asks to be cited, such as `Name the site and link
    /// the post you quote.`
    pub cite: Option<String>,
    /// The owner's words for each other language's copy of the page.
    pub text: BTreeMap<Locale, AiPageText>,
}

/// What one language's copy of the AI info page says in place of the
/// built-in sentences, from `[seo.ai_page.text.<language>]`.
#[derive(Debug, Clone, PartialEq, Eq, Default, Deserialize)]
#[serde(default, deny_unknown_fields)]
#[non_exhaustive]
pub struct AiPageText {
    /// What the site covers, in one sentence, in this language.
    pub covers: Option<String>,
    /// How the site asks to be cited, in this language.
    pub cite: Option<String>,
}

/// What `llms.txt`, the guide to the site for language models, holds, from
/// `[seo.llms_txt]`. The file is written by default and lists every page
/// search engines may list:
///
/// ```toml
/// [seo.llms_txt]
/// intro = "Field Notes is written by two SEO consultants in Leeds."
/// pages = ["/about/", "/editorial-policy/"]
/// exclude = ["/tag/"]
/// ```
#[derive(Debug, Clone, PartialEq, Eq, Default, Deserialize)]
#[serde(default, deny_unknown_fields)]
#[non_exhaustive]
pub struct LlmsTxtSettings {
    /// Switch the file off. `false`, the default, writes it.
    pub off: bool,
    /// Text after the tagline, such as who writes the site.
    pub intro: Option<String>,
    /// Paths inside the mount folder listed first, under "Key pages".
    pub pages: Vec<String>,
    /// Paths inside the mount folder whose pages, and the pages below
    /// them, are left out.
    pub exclude: Vec<String>,
}
